"""Private, evidence-minimized owner review for Registry Change Watch actions."""

from __future__ import annotations

from html import escape
from typing import Any

from .registry_watch import RegistryActionCandidate


def render_owner_action_inbox(candidates: tuple[RegistryActionCandidate, ...]) -> str:
    """Render a private review inbox without exposing raw public-source text."""

    unresolved = tuple(candidate for candidate in candidates if candidate.requires_owner_decision)
    resolved = tuple(candidate for candidate in candidates if not candidate.requires_owner_decision)
    cards = "".join(_candidate_card(candidate) for candidate in unresolved)
    resolved_rows = "".join(_resolved_row(candidate) for candidate in resolved[:12])
    if not cards:
        cards = "<p class='empty'>No registry changes currently need an owner decision.</p>"
    if not resolved_rows:
        resolved_rows = "<p class='empty'>No resolved review items yet.</p>"
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Vice CEO — Owner Review</title><style>
:root{{--ink:#152527;--muted:#607175;--line:#d9e0de;--paper:#fff;--wash:#f4f7f5;--forest:#0e5149;--forest-dark:#083c36;--amber:#8c5b15}}*{{box-sizing:border-box}}body{{margin:0;background:var(--wash);color:var(--ink);font:16px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}main{{max-width:980px;margin:0 auto;padding:54px 28px 100px}}.eyebrow{{margin:0 0 12px;color:var(--forest);font-size:.75rem;font-weight:750;letter-spacing:.09em;text-transform:uppercase}}h1,h2{{font-family:Georgia,"Times New Roman",serif;font-weight:400}}h1{{margin:0 0 13px;font-size:clamp(2.5rem,6vw,4.6rem);line-height:.96;letter-spacing:-.055em}}.lede{{max-width:700px;margin:0 0 38px;color:var(--muted)}}.notice{{margin:0 0 36px;padding:15px 18px;border:1px solid #bdd5cf;background:#eff7f4;color:#204640;font-size:.9rem}}h2{{margin:48px 0 16px;font-size:1.55rem}}.count{{color:var(--forest);font:700 .85rem/1 Inter,ui-sans-serif,sans-serif}}.queue{{display:grid;gap:16px}}.card{{padding:25px;border:1px solid var(--line);background:var(--paper);box-shadow:0 8px 26px rgba(18,39,34,.04)}}.top{{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}}.tag{{display:inline-block;margin-bottom:7px;color:var(--amber);font-size:.75rem;font-weight:750;letter-spacing:.07em;text-transform:uppercase}}h3{{margin:0;font-size:1.1rem}}.meta{{display:grid;grid-template-columns:150px minmax(0,1fr);gap:6px 18px;margin:20px 0;color:var(--muted);font-size:.88rem}}.meta strong{{color:var(--ink);font-weight:650;overflow-wrap:anywhere}}.summary{{margin:18px 0;padding:16px 18px;border-left:3px solid var(--forest);background:#f6f9f8;color:#26383a}}.summary p{{margin:0 0 12px}}.summary p:last-child{{margin-bottom:0}}a{{color:var(--forest);font-weight:650}}.actions{{display:flex;gap:10px;margin-top:22px}}button{{min-height:44px;padding:10px 16px;border:1px solid var(--forest);border-radius:6px;background:#fff;color:var(--forest);font:700 .85rem/1 Inter,ui-sans-serif,sans-serif;cursor:pointer}}button.primary{{background:var(--forest);color:#fff}}button:hover{{background:var(--forest-dark);border-color:var(--forest-dark);color:#fff}}button:disabled{{cursor:wait;opacity:.65}}.resolved{{display:grid;gap:0;border-top:1px solid var(--line);background:var(--paper)}}.resolved article{{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:16px;padding:17px 2px;border-bottom:1px solid var(--line)}}.resolved small{{display:block;color:var(--muted);overflow-wrap:anywhere}}.state{{color:var(--forest);font-size:.8rem;font-weight:750;text-align:right;text-transform:capitalize}}.empty{{padding:24px;border:1px dashed #b8c7c3;color:var(--muted);background:#fff}}#result{{position:fixed;right:24px;bottom:24px;display:none;max-width:390px;padding:14px 16px;border:1px solid var(--line);background:#fff;box-shadow:0 12px 32px rgba(18,39,34,.16);color:var(--ink);font-size:.86rem}}#result.visible{{display:block}}@media(max-width:620px){{main{{padding:36px 20px 80px}}.meta{{grid-template-columns:1fr;gap:2px}}.meta strong{{margin-bottom:8px}}.top{{display:block}}.actions{{display:grid;grid-template-columns:1fr}}.resolved article{{grid-template-columns:1fr}}.state{{text-align:left}}}}
</style></head><body><main><p class="eyebrow">Private Cloud Run owner workspace</p><nav><a href="/owner/registry-operations/console">Operations overview</a><span>Review inbox</span></nav><h1>Registry change<br>review.</h1><p class="lede">Evidence-linked decisions from Westover EPR's approved public registry watch. This workspace cannot contact prospects, change customer records, or make legal conclusions.</p><p class="notice">Access is protected by the private Cloud Run service. Resolving an item records only the owner’s internal review outcome; it does not trigger any downstream business action.</p><h2>Needs your decision <span class="count">{len(unresolved)}</span></h2><section class="queue">{cards}</section><h2>Recently resolved</h2><section class="resolved">{resolved_rows}</section></main><pre id="result" aria-live="polite"></pre><script>const result=document.getElementById('result');document.querySelectorAll('[data-decision]').forEach(button=>button.addEventListener('click',async()=>{{const controls=button.closest('.actions').querySelectorAll('button');controls.forEach(control=>control.disabled=true);result.classList.add('visible');result.textContent='Recording owner review…';try{{const response=await fetch('/owner/registry-actions/'+encodeURIComponent(button.dataset.candidateId)+'/decision',{{method:'POST',headers:{{'content-type':'application/json'}},body:JSON.stringify({{decision:button.dataset.decision}})}});const payload=await response.json();if(!response.ok)throw new Error(payload.detail||'Unable to record review');result.textContent='Owner review recorded. Refreshing…';setTimeout(()=>location.reload(),650)}}catch(error){{result.textContent='No review was recorded: '+error.message;controls.forEach(control=>control.disabled=false)}}}}));</script></body></html>"""


def render_owner_operations_console(overview: dict[str, object]) -> str:
    """Render compact private operating state without page bodies or customer data."""

    sources = overview.get("source_portfolio", [])
    queue = overview.get("owner_action_queue", {})
    safety = overview.get("safety", {})
    authority = overview.get("authority", {})
    source_cards = "".join(_source_card(source) for source in sources if isinstance(source, dict))
    if not source_cards:
        source_cards = "<p class='empty'>No approved registry sources are configured.</p>"
    awaiting = _count(queue, "awaiting_owner_decision")
    resolved = _count(queue, "resolved")
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Vice CEO — Registry Operations</title><style>
:root{{--ink:#152527;--muted:#607175;--line:#d9e0de;--paper:#fff;--wash:#f4f7f5;--forest:#0e5149;--forest-dark:#083c36;--amber:#8c5b15}}*{{box-sizing:border-box}}body{{margin:0;background:var(--wash);color:var(--ink);font:16px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}main{{max-width:1080px;margin:0 auto;padding:54px 28px 100px}}nav{{display:flex;gap:14px;margin:0 0 30px;color:var(--muted);font-size:.86rem}}nav a{{color:var(--forest);font-weight:750}}.eyebrow{{margin:0 0 12px;color:var(--forest);font-size:.75rem;font-weight:750;letter-spacing:.09em;text-transform:uppercase}}h1,h2,h3{{font-family:Georgia,"Times New Roman",serif;font-weight:400}}h1{{margin:0 0 13px;font-size:clamp(2.5rem,6vw,4.6rem);line-height:.96;letter-spacing:-.055em}}h2{{margin:46px 0 16px;font-size:1.55rem}}h3{{margin:0;font-size:1.18rem}}.lede{{max-width:750px;margin:0 0 28px;color:var(--muted)}}.notice{{margin:0;padding:15px 18px;border:1px solid #bdd5cf;background:#eff7f4;color:#204640;font-size:.9rem}}.stats{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:24px}}.stat,.source,.control{{padding:22px;border:1px solid var(--line);background:var(--paper);box-shadow:0 8px 26px rgba(18,39,34,.04)}}.stat strong{{display:block;margin-top:4px;font:400 2.2rem/1 Georgia,"Times New Roman",serif;color:var(--forest)}}.stat span,.label{{color:var(--muted);font-size:.78rem;font-weight:750;letter-spacing:.07em;text-transform:uppercase}}.sources{{display:grid;gap:14px}}.source-top{{display:flex;gap:18px;justify-content:space-between;align-items:flex-start}}.pill{{padding:4px 8px;border:1px solid #bdd5cf;color:var(--forest);font-size:.74rem;font-weight:750;white-space:nowrap}}.source p{{margin:14px 0;color:#35484a}}.meta{{display:grid;grid-template-columns:155px minmax(0,1fr);gap:6px 18px;margin:18px 0 0;color:var(--muted);font-size:.86rem}}.meta strong{{color:var(--ink);font-weight:650;overflow-wrap:anywhere}}.controls{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}}.control p{{margin:8px 0 0;color:var(--muted)}}.empty{{padding:24px;border:1px dashed #b8c7c3;color:var(--muted);background:#fff}}a{{color:var(--forest);font-weight:650}}@media(max-width:700px){{main{{padding:36px 20px 80px}}.stats,.controls{{grid-template-columns:1fr}}.source-top{{display:block}}.pill{{display:inline-block;margin-top:10px}}.meta{{grid-template-columns:1fr;gap:2px}}.meta strong{{margin-bottom:8px}}}}
</style></head><body><main><p class="eyebrow">Private Cloud Run owner workspace</p><nav><span>Operations overview</span><a href="/owner/registry-actions/inbox">Review inbox</a></nav><h1>Registry watch<br>operations.</h1><p class="lede">A compact view of approved sources, durable evidence, review workload, and the system's deliberately limited authority.</p><p class="notice">This service stores evidence metadata rather than raw page bodies. It cannot contact prospects, alter customer records, or make a legal or regulatory conclusion.</p><section class="stats"><article class="stat"><span>Approved sources</span><strong>{len(sources)}</strong></article><article class="stat"><span>Owner decisions pending</span><strong>{awaiting}</strong></article><article class="stat"><span>Resolved reviews</span><strong>{resolved}</strong></article></section><h2>Approved public-source portfolio</h2><section class="sources">{source_cards}</section><h2>Safety and authority</h2><section class="controls"><article class="control"><span class="label">Untrusted-source gate</span><p>{escape(str(safety.get("suspicious_content_behavior", "not_available")).replace("_", " "))}. Version: {escape(str(safety.get("untrusted_source_safety_version", "not_available")))}</p></article><article class="control"><span class="label">Authority boundary</span><p>External business actions: {escape(str(authority.get("external_business_actions_enabled", False)).lower())}. Customer-record mutation: {escape(str(authority.get("customer_record_mutation", False)).lower())}. Legal conclusions: {escape(str(authority.get("legal_or_regulatory_conclusion", False)).lower())}.</p></article></section></main></body></html>"""


def _source_card(source: dict[str, Any]) -> str:
    evidence = source.get("latest_evidence")
    if isinstance(evidence, dict):
        evidence_rows = f"""<span>Latest capture</span><strong>{escape(str(evidence.get("captured_at", "not_available")))}</strong><span>Source version</span><strong>{escape(str(evidence.get("source_version", "not_available")))}</strong><span>Evidence hash</span><strong>{escape(str(evidence.get("evidence_sha256", "not_available")))}</strong><span>Segments hashed</span><strong>{escape(str(evidence.get("content_segment_count", "not_available")))}</strong>"""
        state = "Evidence captured"
    else:
        evidence_rows = "<span>Latest evidence</span><strong>No durable snapshot captured yet</strong>"
        state = "Awaiting baseline"
    return f"""<article class="source"><div class="source-top"><div><h3>{escape(str(source.get("display_name", "Approved registry source")))}</h3><p>{escape(str(source.get("operational_focus", "Public EPR program update")))}</p></div><span class="pill">{escape(state)}</span></div><div class="meta"><span>Jurisdiction</span><strong>{escape(str(source.get("jurisdiction", "not_available")))}</strong><span>Source owner</span><strong>{escape(str(source.get("source_owner", "not_available")))}</strong><span>Refresh cadence</span><strong>{escape(str(source.get("refresh_schedule", "not_available")))}</strong>{evidence_rows}</div><p><a href="{escape(str(source.get("canonical_url", "#")), quote=True)}" target="_blank" rel="noreferrer">Open official public source</a></p></article>"""


def _count(mapping: object, key: str) -> int:
    if not isinstance(mapping, dict):
        return 0
    value = mapping.get(key, 0)
    return value if isinstance(value, int) and value >= 0 else 0


def _candidate_card(candidate: RegistryActionCandidate) -> str:
    return f"""<article class="card"><div class="top"><div><span class="tag">Owner decision required</span><h3>{escape(candidate.action_type.replace("_", " "))}</h3></div></div><div class="meta"><span>Jurisdiction</span><strong>{escape(candidate.jurisdiction)}</strong><span>Evidence hash</span><strong>{escape(candidate.evidence_sha256)}</strong><span>Created</span><strong>{escape(candidate.created_at)}</strong></div><div class="summary"><p><strong>What changed</strong><br>{escape(candidate.review_summary or "A bounded change brief is available for review.")}</p><p><strong>Recommended next step</strong><br>{escape(candidate.recommended_next_action or "Review the cited source before deciding on any follow-up.")}</p></div><p><a href="{escape(candidate.source_citation_url, quote=True)}" target="_blank" rel="noreferrer">Open official public source</a></p><div class="actions"><button type="button" data-candidate-id="{escape(candidate.candidate_id, quote=True)}" data-decision="archive">Archive internal review</button><button type="button" class="primary" data-candidate-id="{escape(candidate.candidate_id, quote=True)}" data-decision="acknowledge">Acknowledge and prepare review</button></div></article>"""


def _resolved_row(candidate: RegistryActionCandidate) -> str:
    return f"""<article><div><strong>{escape(candidate.action_type.replace("_", " "))}</strong><small>{escape(candidate.jurisdiction)} · {escape(candidate.created_at)} · {escape(candidate.evidence_sha256)}</small></div><span class="state">{escape(candidate.status.replace("_", " "))}</span></article>"""
